//! HF `transformers` Oracle checks for the EmbeddingGemma-2 image/audio paths.
//!
//! The fixture is generated by `tests/oracle/run_embeddinggemma2_multimodal_oracle.py`
//! from the local HF model under `models/embeddinggemma-2` and uses the same
//! synthetic inputs as the Rust smoke tests. It deliberately checks both the
//! raw tower and projected text-space outputs so a shape-only implementation
//! cannot pass.

use std::sync::Arc;

fn oracle() -> serde_json::Value {
    serde_json::from_str(
        &std::fs::read_to_string("tests/oracle/embeddinggemma2_multimodal.json")
            .expect("missing EmbeddingGemma multimodal Oracle"),
    )
    .expect("invalid EmbeddingGemma multimodal Oracle")
}

fn vector(value: &serde_json::Value, key: &str) -> Vec<f32> {
    value[key]
        .as_array()
        .unwrap_or_else(|| panic!("Oracle field {key} is not an array"))
        .iter()
        .map(|item| item.as_f64().expect("Oracle value is not a number") as f32)
        .collect()
}

fn compare(label: &str, actual: &[f32], expected: &[f32]) {
    assert_eq!(
        actual.len(),
        expected.len(),
        "{label}: output shape differs"
    );
    let mut dot = 0.0f64;
    let mut actual_norm = 0.0f64;
    let mut expected_norm = 0.0f64;
    let mut diff = 0.0f64;
    for (&a, &b) in actual.iter().zip(expected) {
        let a = f64::from(a);
        let b = f64::from(b);
        dot += a * b;
        actual_norm += a * a;
        expected_norm += b * b;
        diff += (a - b) * (a - b);
    }
    let cosine = dot / (actual_norm * expected_norm).sqrt();
    let relative_l2 = diff.sqrt() / expected_norm.sqrt();
    eprintln!("{label}: cosine={cosine:.7}, relative_l2={relative_l2:.7}");
    assert!(cosine > 0.99999, "{label}: cosine {cosine:.7} < 0.99999");
    assert!(
        relative_l2 < 0.0001,
        "{label}: relative L2 {relative_l2:.7} >= 0.0001"
    );
}

#[test]
fn vision_matches_huggingface_oracle() {
    let Some(path) = std::env::var_os("RMI_EMBEDDINGGEMMA_2") else {
        return;
    };
    let loader = rust_model_inference::GGUFLoader::from_file(path).expect("load GGUF");
    let source: Arc<dyn rust_model_inference::TensorSource> = Arc::new(loader);
    let model =
        rust_model_inference::models::embeddinggemma2::EmbeddingGemmaVisionModel::from_source(
            &source,
        )
        .expect("EmbeddingGemmaVisionModel::from_source");
    let image_h = 48;
    let image_w = 48;
    let pixels: Vec<f32> = (0..image_h * image_w * 3)
        .map(|i| (i as f32 * 0.001).sin() * 0.5 + 0.5)
        .collect();
    let oracle = oracle();
    let tower = model
        .encode_tower(&pixels, image_h, image_w)
        .expect("vision tower");
    compare("vision tower", &tower, &vector(&oracle, "vision_tower"));
    let text = model
        .encode(&pixels, image_h, image_w)
        .expect("vision text");
    compare("vision text", &text, &vector(&oracle, "vision_text"));
    compare_embedding(&source, &oracle, "vision", 258880, &text);
}

#[test]
fn audio_matches_huggingface_oracle() {
    let Some(path) = std::env::var_os("RMI_EMBEDDINGGEMMA_2") else {
        return;
    };
    let loader = rust_model_inference::GGUFLoader::from_file(path).expect("load GGUF");
    let source: Arc<dyn rust_model_inference::TensorSource> = Arc::new(loader);
    let model =
        rust_model_inference::models::embeddinggemma2::EmbeddingGemmaAudioModel::from_source(
            &source,
        )
        .expect("EmbeddingGemmaAudioModel::from_source");
    // Keep the fixture integer-defined so Rust and NumPy do not disagree on
    // libm rounding while generating an otherwise identical waveform.
    let pcm: Vec<i16> = (0..16000)
        .map(|i| ((i * 37) % 20_001) as i16 - 10_000)
        .collect();
    let oracle = oracle();
    let tower = model.encode_tower(&pcm).expect("audio tower");
    compare("audio tower", &tower, &vector(&oracle, "audio_tower"));
    let text = model.encode(&pcm).expect("audio text");
    compare("audio text", &text, &vector(&oracle, "audio_text"));
    compare_embedding(&source, &oracle, "audio", 258881, &text);
}

fn compare_embedding(
    source: &Arc<dyn rust_model_inference::TensorSource>,
    oracle: &serde_json::Value,
    kind: &str,
    token_id: u32,
    soft_tokens: &[f32],
) {
    let ids: Vec<u32> = oracle[format!("{kind}_token_ids")]
        .as_array()
        .unwrap()
        .iter()
        .map(|id| id.as_u64().unwrap() as u32)
        .collect();
    let model =
        rust_model_inference::models::embeddinggemma2::EmbeddingGemmaTextModel::from_source(
            source.as_ref(),
        )
        .unwrap();
    assert!(model
        .forward_with_soft_tokens(&ids, token_id, &soft_tokens[..soft_tokens.len() - 1])
        .is_err());
    let actual = model
        .forward_with_soft_tokens(&ids, token_id, soft_tokens)
        .unwrap();
    let expected = vector(oracle, &format!("{kind}_embedding"));
    assert_eq!(actual.len(), 768);
    let norm: f64 = expected.iter().map(|&v| f64::from(v).powi(2)).sum();
    let diff: f64 = actual
        .iter()
        .zip(&expected)
        .map(|(&a, &b)| (f64::from(a) - f64::from(b)).powi(2))
        .sum();
    let relative_l2 = (diff / norm).sqrt();
    eprintln!("{kind} final embedding relative L2 = {relative_l2:.8}");
    // Text projections use Q8_0, unlike the BF16 vision/audio tower fixtures.
    assert!(
        relative_l2 < 0.02,
        "{kind} final embedding relative L2 {relative_l2}"
    );
}
